" f"Let's think step by step.
" f"Answer: {answer}
" ) return ( f"Question: {question}
" f"Answer: {answer}
" ) def build_prompt(item: dict[str, Any], cfg: DictConfig) -&gt; str: input_field = cfg.dataset.input_field question = item.get(input_field, "") template = cfg.method.prompt_template num_shots = cfg.method.num_shots examples = FEW_SHOT_EXAMPLES.get(cfg.dataset.name, []) selected_examples = examples[:num_shots] prompt_parts = [] for example in selected_examples: prompt_parts.append( format_example( question=example["question"], answer=example["answer"], template=template, ) ) if template == "chain_of_thought": prompt_parts.append( f"Question: {question}
" f"Let's think step by step.
