".join(prompt_parts) # ---------------------------- # 7. Evaluation # ---------------------------- def extract_prediction(text: str) -&gt; str: # 示例函数。真实 benchmark 应使用任务对应的严格解析器。 return text.strip() def simple_exact_match(prediction: str, reference: str) -&gt; bool: return reference.strip() in prediction.strip() def evaluate(model_dict: dict[str, Any], dataset, cfg: DictConfig) -&gt; dict[str, Any]: model = model_dict["model"] tokenizer = model_dict["tokenizer"] logger.info("Running evaluation with method: %s", cfg.method.name) model.eval() total = 0 correct = 0 predictions = [] do_sample = bool(cfg.generation.do_sample or cfg.method.temperature &gt; 0) generation_kwargs = { "max_new_tokens": cfg.generation.max_new_tokens, "do_sample": do_sample, "top_p": float(cfg.method.top_p), "pad_token_id": tokenizer.pad_token_id, } if do_sample: generation_kwargs["temperature"] = float(cfg.method.temperature) with torch.no_grad(): for item in dataset: prompt = build_prompt(item, cfg) inputs = tokenizer( prompt, return_tensors="pt", truncation=True, max_length=cfg.model.max_length, ) # 兼容 device_map="auto" 和普通 .to(device) 两种路径。 if not hasattr(model, "hf_device_map"): inputs = inputs.to(model.device) else: first_device = next(model.parameters()).device inputs = inputs.to(first_device) outputs = model.generate( **inputs, **generation_kwargs, ) generated_text = tokenizer.decode( outputs[0], skip_special_tokens=True, ) prediction = extract_prediction(generated_text) reference = str(item.get(cfg.dataset.answer_field, "")) is_correct = simple_exact_match(prediction, reference) total += 1 correct += int(is_correct) predictions.append( { "prompt": prompt, "prediction": prediction, "reference": reference, "correct": is_correct, } ) score = correct / total if total &gt; 0 else 0.0 result = { "model": cfg.model.name, "pretrained_name": cfg.model.pretrained_name, "dataset": cfg.dataset.name, "method": cfg.method.name, "metric": cfg.dataset.metric, "score": round(score, 4), "num_samples": total, "hyperparams": { "seed": cfg.seed, "lr": cfg.lr, "batch_size": cfg.batch_size, "epochs": cfg.epochs, "temperature": cfg.method.temperature, "top_p": cfg.method.top_p, "num_shots": cfg.method.num_shots, "max_new_tokens": cfg.generation.max_new_tokens, }, "runtime": { "accelerator": cfg.runtime.accelerator, "visible_devices": cfg.runtime.visible_devices, "device_map": cfg.runtime.device_map, "precision": cfg.runtime.precision, }, } return result, predictions # ---------------------------- # 8. Main # ---------------------------- @hydra.main(version_base=None, config_path="conf", config_name="config") def main(cfg: DictConfig) -&gt; None: logger.info("Starting experiment") # 解析并校验完整配置。 validate_cfg(cfg) set_seed(int(cfg.seed)) logger.info( "
