%s", OmegaConf.to_yaml(cfg, resolve=True), ) model_dict = build_model(cfg) dataset = build_dataset(cfg) result, predictions = evaluate(model_dict, dataset, cfg) output_dir = Path(cfg.output_dir) output_dir.mkdir(parents=True, exist_ok=True) config_path = output_dir / "config_resolved.yaml" with open(config_path, "w", encoding="utf-8") as f: f.write(OmegaConf.to_yaml(cfg, resolve=True)) result_path = output_dir / "result.json" with open(result_path, "w", encoding="utf-8") as f: json.dump(result, f, indent=2, ensure_ascii=False) predictions_path = output_dir / "predictions.jsonl" with open(predictions_path, "w", encoding="utf-8") as f: for row in predictions: f.write(json.dumps(row, ensure_ascii=False) + "
